def canVisitAllRooms(rooms: list[list[int]]) -> bool:
    visited = set([0])
    stack = [0]
    while stack:
        r = stack.pop()
        for k in rooms[r]:
            if k not in visited:
                visited.add(k)
                stack.append(k)
    return len(visited) == len(rooms)

